import { RETIRED_ASSISTANT_EXAMPLE_REQUESTS } from "../retiredAssistant.js";
import { bitfabKit } from "./kit.js";
const EXAMPLE_LINES = RETIRED_ASSISTANT_EXAMPLE_REQUESTS.map((request) => `> - "${request}"`).join("\n");
export const assistantFlow = bitfabKit.defineFlow({
    schemaVersion: 1,
    id: "assistant",
    title: "Bitfab Assistant (retired)",
    frontmatter: {
        description: "Retired. Only use when the user explicitly types the bitfab assistant command by name; it tells them the assistant has been retired. Never use it for requests about traces, datasets, labels, verdicts, replays, experiments, or improving a traced function: handle those directly with the Bitfab MCP tools",
    },
    entries: {
        default: "retired/explain",
    },
    defaultMode: "default",
    phases: [
        {
            id: "retired",
            title: "Retired",
            stepStyle: "list",
            steps: [
                {
                    id: "explain",
                    kind: "action",
                    title: "Tell the user the assistant is retired",
                    body: `Do not start any work. Tell the user the following, then stop:

> The Bitfab Assistant (\`{{cmd}}assistant\`) has been retired. You no longer need a special command: just tell your agent what you want, and it will use the Bitfab tools to do it. For example:
>
${EXAMPLE_LINES}
>
> To instrument new code or set up replay, use \`{{cmd}}setup\`.

If the user passed arguments along with the command, offer to do that request directly now, without the assistant.`,
                    next: null,
                },
            ],
        },
    ],
});
